const pessoa = { nome: 'Ana', idade: 30 };

const handler = {
  get(alvo, propriedade) {
    console.log(`A ler a propriedade "${String(propriedade)}"`);
    return alvo[propriedade];
  }
};

const pessoaVigiada = new Proxy(pessoa, handler);

console.log(pessoaVigiada.nome);  // regista o acesso e devolve 'Ana'
console.log(pessoaVigiada.idade); // regista o acesso e devolve 30

function criarContaValidada(saldoInicial) {
  const estado = { saldo: saldoInicial };

  return new Proxy(estado, {
    set(alvo, propriedade, valor) {
      if (propriedade === 'saldo') {
        if (typeof valor !== 'number' || Number.isNaN(valor)) {
          throw new TypeError('O saldo tem de ser um número válido.');
        }
        if (valor < 0) {
          throw new RangeError('O saldo não pode ser negativo.');
        }
      }
      alvo[propriedade] = valor;
      return true;
    }
  });
}

const conta = criarContaValidada(100);
conta.saldo = 250; // aceite
// conta.saldo = -50; // lança RangeError automaticamente

const dadosInternos = { id: 1, nome: 'Catálogo', _tokenInterno: 'abc123' };

const catalogo = new Proxy(dadosInternos, {
  has(alvo, propriedade) {
    if (String(propriedade).startsWith('_')) return false; // esconde campos privados
    return propriedade in alvo;
  },
  deleteProperty(alvo, propriedade) {
    if (propriedade === 'id') {
      throw new Error('A propriedade "id" não pode ser removida.');
    }
    delete alvo[propriedade];
    return true;
  }
});

console.log('_tokenInterno' in catalogo); // false, mesmo existindo no alvo
console.log('nome' in catalogo);           // true
delete catalogo.nome; // permitido
// delete catalogo.id; // lança erro

const utilizadorBase = { primeiroNome: 'Maria', ultimoNome: 'Santos' };

const utilizador = new Proxy(utilizadorBase, {
  get(alvo, propriedade, receiver) {
    if (propriedade === 'nomeCompleto') {
      return `${alvo.primeiroNome} ${alvo.ultimoNome}`;
    }
    if (typeof propriedade === 'string' && !(propriedade in alvo)) {
      return `(propriedade "${propriedade}" não definida)`;
    }
    return Reflect.get(alvo, propriedade, receiver);
  }
});

console.log(utilizador.nomeCompleto); // 'Maria Santos', calculado na hora
utilizadorBase.ultimoNome = 'Costa';
console.log(utilizador.nomeCompleto); // 'Maria Costa', já reflete a mudança
console.log(utilizador.morada);       // '(propriedade "morada" não definida)'

function comLogging(alvo, nomeObjeto = 'objeto') {
  return new Proxy(alvo, {
    get(alvoReal, propriedade, receiver) {
      const valor = Reflect.get(alvoReal, propriedade, receiver);
      console.log(`[${nomeObjeto}] leitura de "${String(propriedade)}" ->`, valor);
      return valor;
    },
    set(alvoReal, propriedade, valor, receiver) {
      console.log(`[${nomeObjeto}] escrita em "${String(propriedade)}": ${alvoReal[propriedade]} -> ${valor}`);
      return Reflect.set(alvoReal, propriedade, valor, receiver);
    }
  });
}

const config = comLogging({ tema: 'claro', idioma: 'pt-PT' }, 'config');
config.idioma;        // regista leitura
config.tema = 'escuro'; // regista escrita: 'claro' -> 'escuro'

const alvo = {
  _valor: 10,
  get valor() {
    return this._valor;
  },
  set valor(novo) {
    this._valor = novo;
  }
};

const handlerCorreto = {
  get(alvoReal, propriedade, receiver) {
    console.log(`get: ${String(propriedade)}`);
    return Reflect.get(alvoReal, propriedade, receiver); // preserva o "this" correto
  },
  set(alvoReal, propriedade, valor, receiver) {
    console.log(`set: ${String(propriedade)} = ${valor}`);
    return Reflect.set(alvoReal, propriedade, valor, receiver);
  }
};

const proxyCorreto = new Proxy(alvo, handlerCorreto);
proxyCorreto.valor = 99; // "this" no setter é o proxy, não o alvo
console.log(proxyCorreto.valor);

