const livro = { titulo: 'Duna', autor: 'Frank Herbert' };

const livroVigiado = new Proxy(livro, {
  get(alvo, propriedade) {
    console.log(`Acesso a "${String(propriedade)}"`);
    return alvo[propriedade];
  }
});

console.log(livroVigiado.titulo); // Acesso a "titulo" / Duna
console.log(livroVigiado.autor);  // Acesso a "autor" / Frank Herbert

const produto = { nome: 'Teclado', preco: 50, stock: 10 };

const produtoValidado = new Proxy(produto, {
  set(alvo, propriedade, valor) {
    if (propriedade === 'preco') {
      if (typeof valor !== 'number' || Number.isNaN(valor)) {
        throw new TypeError('O preço tem de ser um número.');
      }
      if (valor <= 0) {
        throw new RangeError('O preço tem de ser maior que zero.');
      }
    }

    if (propriedade === 'stock') {
      if (typeof valor !== 'number' || Number.isNaN(valor)) {
        throw new TypeError('O stock tem de ser um número.');
      }
      if (!Number.isInteger(valor) || valor < 0) {
        throw new RangeError('O stock tem de ser um inteiro maior ou igual a zero.');
      }
    }

    alvo[propriedade] = valor;
    return true;
  }
});

produtoValidado.preco = 75; // aceite
produtoValidado.nome = 'Teclado mecânico'; // aceite, sem validação
// produtoValidado.stock = -3; // lançaria RangeError
// produtoValidado.preco = 'grátis'; // lançaria TypeError

const sessaoUtilizador = { id: 42, nome: 'Rita', _tokenSessao: 'xyz987' };

const sessaoPublica = new Proxy(sessaoUtilizador, {
  has(alvo, propriedade) {
    if (String(propriedade).startsWith('_')) {
      return false;
    }
    return propriedade in alvo;
  },
  deleteProperty(alvo, propriedade) {
    if (propriedade === 'id') {
      throw new Error('Não é possível remover o id.');
    }
    delete alvo[propriedade];
    return true;
  }
});

console.log('_tokenSessao' in sessaoPublica); // false, mesmo existindo no alvo
console.log('nome' in sessaoPublica); // true

delete sessaoPublica.nome; // permitido
// delete sessaoPublica.id; // lançaria Error

function tornarSomenteLeitura(objeto, excecoes = []) {
  return new Proxy(objeto, {
    get(alvo, propriedade, receiver) {
      return Reflect.get(alvo, propriedade, receiver);
    },
    set(alvo, propriedade, valor, receiver) {
      if (!excecoes.includes(propriedade)) {
        throw new TypeError(`A propriedade "${String(propriedade)}" é só de leitura.`);
      }
      return Reflect.set(alvo, propriedade, valor, receiver);
    },
    deleteProperty() {
      throw new TypeError('Não é permitido remover propriedades.');
    }
  });
}

const baseConfig = {
  _tema: 'claro',
  get tema() {
    return this._tema;
  }
};

const config = tornarSomenteLeitura(baseConfig, ['_tema']);

console.log(config.tema); // 'claro', o getter herdado funciona através do Reflect.get
config._tema = 'escuro';  // permitido, está nas exceções
console.log(config.tema); // 'escuro'

// config.tema = 'azul'; // lançaria TypeError, "tema" não está nas exceções
// delete config._tema;  // lançaria TypeError
